def _get_workplan_groups(plan) -> list:
    """Extract the list of WorkGroup objects from a plan, or empty list."""
    workplan = getattr(plan, 'workplan', None)
    if not workplan:
        strategy = getattr(plan, 'strategy', None)
        if strategy:
            workplan = getattr(strategy, 'parallelisable_workplan', None)
    return getattr(workplan, 'groups', []) if workplan else []


def _collect_tasks(groups: list) -> list:
    """Flatten all tasks from a list of WorkGroup objects."""
    tasks: list = []
    for group in groups:
        tasks.extend(getattr(group, 'tasks', []) or [])
    return tasks


def _check_task_files(task, seen: set[str], violations: list[str]) -> None:
    """Validate that a task has exactly 1 file_path and no collisions."""
    fps = getattr(task, 'file_paths', None) or []
    if len(fps) != 1:
        violations.append(f"task {getattr(task, 'id', '?')} lists {len(fps)} files (exactly 1 required)")
    for fp in fps:
        if fp in seen:
            violations.append(f'file collision: {fp} in multiple tasks')
        seen.add(fp)"}
